import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.logging.Logger;
import java.util.stream.Stream;

public class FolderUtils {
    public static boolean copyFolder(File source, File target, Logger log) {
        Path sourcePath = source.toPath();
        Path targetPath = target.toPath();

        try (Stream<Path> files = Files.walk(sourcePath)) {
            files.forEachOrdered(srcPath -> {
                Path destPath = targetPath.resolve(sourcePath.relativize(srcPath));
                try {
                    if (Files.isDirectory(srcPath)) {
                        if (!Files.exists(destPath)) {
                            Files.createDirectories(destPath);
                        }
                    } else {
                        Files.copy(srcPath, destPath, StandardCopyOption.REPLACE_EXISTING);
                    }
                } catch (IOException e) {
                    log.warning("Failed to copy: " + srcPath.toString() + " - " + e.getMessage());
                }
            });
            return true;
        } catch (IOException e) {
            log.warning("Failed to copy folder: " + e.getMessage());
            return false;
        }
    }
}
